def doc_so_coc(raw):
    coc = float(raw)
    if not 0 <= coc <= 50:
        raise ValueError("Ngoai 0..50")
    return coc

try:
    doc_so_coc("99")
except ValueError as error:
    print(str(error))

try:
    number = int("8")
except ValueError:
    print("invalid")
else:
    print(number)
